insert into public.traits (key, icon, name, family, min_age, varies_by_place, low_name, low_self, low_others, mid_name, mid_text, high_name, high_self, high_others, place_note, position) values
('gratitude','🙏','Gratitude','Character',6,false,'Never thankful','Always feels something is missing; envies others more easily.','People feel used and unappreciated.','Grateful','Notices the good things and the people behind them, and says thank you.','Thanks for everything, even harm','Accepts unfair treatment and calls it kindness.','Others may take advantage of it.',null,20),
('thinking','🌈','Black-and-white ⇄ shades of grey','Mindset',8,false,'Black-and-white','Sees people as all good or all bad; one mistake ruins everything.','Judges others quickly and harshly; friendships break suddenly.','Shades of grey','Sees that people and things are mixed, and still knows right from wrong.','Everything is grey','Never takes a stand, even when something is clearly wrong.','Others can''t count on them to say "this is wrong".',null,21),
('assertive','🦁','Strength of personality','Character',7,true,'Passive (weak)','Can''t say no; keeps feelings inside until they explode.','Others decide for them and may take advantage.','Assertive','Says what they think and need, calmly and with respect.','Aggressive','Wins arguments but loses friends.','Pushes, shouts or threatens to get their way.','Some people are strong at home but can''t speak up at school or work, or the other way round.',22)
insert into public.signs (key, icon, name, category, min_age, about, academic, position) values
('needs_admiration','👏','Needs to be admired','self',10,'Always wants praise and attention.','Excessive need for admiration; self-esteem is regulated by outside validation.',0),
('grandiosity','👑','Feels more special than others','self',10,'Thinks they are better than others and deserve special treatment.','Grandiose sense of self-importance; fantasies of unlimited success, power or brilliance.',1),
('entitlement','🎫','Expects special treatment','self',10,'Expects the rules not to apply to them.','Sense of entitlement: unreasonable expectations of favourable treatment or automatic compliance.',2),
('arrogant_attitude','🦚','Looks down on people','self',10,'Acts proud and talks down to others.','Arrogant, haughty behaviours or attitudes.',3),
('fragile_self_esteem','🥚','Fragile self-esteem','self',10,'Looks confident, but is hurt very easily.','Unstable self-esteem that reacts strongly to perceived threats.',4),
('hidden_superiority','🫥','Quietly feels superior','self',14,'Seems shy or modest, but secretly feels better than others and not appreciated enough.','Covert grandiosity masked by apparent modesty, shyness or self-criticism (vulnerable narcissism).',5),
('hypersensitive_criticism','🌵','Can''t take criticism','self',8,'Small comments feel like big attacks.','Hypersensitivity to criticism; shame or anger in response to perceived slights.',6),
('unstable_identity','🎭','Unsure who they are','self',14,'Keeps changing goals, friends, values and even style.','Identity disturbance: markedly and persistently unstable self-image or sense of self.',7),
('feels_empty','🕳️','Feels empty inside','self',14,'Often feels hollow, as if something is missing inside.','Chronic feelings of emptiness.',8),
('feels_inadequate','😞','Feels not good enough','self',8,'Believes they are worse than others.','Pervasive feelings of inadequacy; views self as socially inept or inferior.',9),
('inferiority','📉','Feels below someone','self',8,'Feels smaller than a particular person, in something that matters to them.','Perceived inferiority to a similar other in a self-relevant domain: the starting point of envy.',10),
('no_try','🪫','Gives up before trying','self',7,'Says "I can''t" before even starting.','Avoidance driven by an expectation of failure.',11),
('mood_swings','🎢','Feelings change fast','feelings',10,'Can be happy, then angry, then sad within hours.','Affective instability: intense episodes of low mood, irritability or anxiety usually lasting hours.',12),
('intense_anger','🌋','Sudden strong anger','feelings',8,'Gets very angry very fast, more than the situation needs.','Inappropriate, intense anger or difficulty controlling anger.',13),
('shallow_emotions','🎈','Big feelings that don''t go deep','feelings',14,'Shows huge feelings that change quickly and seem not very deep.','Rapidly shifting and shallow expression of emotions.',14),
('cold_emotions','🧊','Shows very little feeling','feelings',12,'Hardly shows joy, sadness or anger.','Emotional coldness, detachment or flattened affect.',15),
('fear_abandonment','🚪','Terrified of being left','feelings',12,'Panics at the idea that someone will leave them.','Frantic efforts to avoid real or imagined abandonment.',16),
('envy_others','💚','Envies others','feelings',7,'Feels bad when others have what they want.','Frequently envious of others, or believes others are envious of them.',17),
('jealous_rival','🫣','Afraid of being replaced','feelings',7,'Worries that someone will take a friend or a parent''s love away.','Jealousy: perceived threat of losing a valued relationship to a rival.',18),
('no_remorse','🚫','Doesn''t feel sorry','feelings',12,'Hurts people and doesn''t feel bad about it.','Lack of remorse: indifferent to, or rationalising, having hurt or mistreated others.',19),
('enjoys_suffering','🖤','Enjoys others'' pain','feelings',16,'Feels pleased when others are hurt or humiliated.','Derives pleasure from others'' suffering or humiliation (sadistic tendency).',20),
('schadenfreude','😏','Happy when others fail','feelings',10,'Smiles inside when someone else has bad luck.','Schadenfreude: pleasure at another''s misfortune, closely linked to malicious envy.',21),
('anxiety_social','😰','Very nervous with people','feelings',8,'Feels scared and awkward around others.','Social anxiety and inhibition in interpersonal situations.',22),
('shame_prone','😳','Feels ashamed easily','feelings',10,'Feels deeply embarrassed, as if something is wrong with them.','Proneness to shame (a global negative evaluation of the self).',23),
('resentment_brewing','😤','Holds grudges','feelings',8,'Never forgets or forgives a hurt.','Persistently bears grudges; unforgiving of insults, injuries or slights.',24),
('black_white_thinking','⚫','Black-and-white thinking','thinking',8,'People are all good or all bad; there is no middle.','Dichotomous thinking ("splitting"): others and events are seen in all-or-nothing terms.',25),
('idealize_devalue','🔄','Loves you, then hates you','thinking',12,'First thinks you''re perfect, then suddenly thinks you''re terrible.','Alternation between extremes of idealisation and devaluation.',26),
('suspicious','🕵️','Suspects everyone','thinking',10,'Thinks people are secretly against them, without proof.','Pervasive distrust: suspects, without sufficient basis, that others are exploiting, harming or deceiving them.',27),
('reads_threats','🎯','Hears insults in normal words','thinking',10,'Takes friendly words as hidden attacks.','Reads hidden demeaning or threatening meanings into benign remarks or events.',28),
('wont_confide','🔒','Won''t share anything personal','thinking',10,'Never tells anyone their worries, in case it is used against them.','Reluctant to confide in others for fear the information will be used maliciously.',29),
('odd_beliefs','🔮','Unusual beliefs','thinking',14,'Believes in strange powers or signs that others don''t.','Odd beliefs or magical thinking inconsistent with cultural norms.',30),
('perfectionism','📏','Everything must be perfect','thinking',10,'Can''t finish work because it''s never perfect enough.','Perfectionism that interferes with completing tasks.',31),
('rigid_rules','📐','Rules matter more than people','thinking',12,'Loves lists, order and rules so much that the point gets lost.','Preoccupation with details, rules, lists and order; rigidity and stubbornness.',32),
('zero_sum','🥧','"Your win is my loss"','thinking',9,'Believes that if someone else wins, they lose.','Zero-sum beliefs: perceiving others'' gains as one''s own losses.',33),
('victim_mindset','🥺','Always the victim','thinking',10,'Whatever happens, they feel it was done to them.','Habitual self-presentation as a victim; blame is placed outside the self.',34),
('intrusive_thoughts','🔁','Unwanted thoughts that repeat','thinking',12,'Worrying thoughts pop up again and again, even when they don''t want them.','Recurrent, intrusive and unwanted thoughts, urges or images causing distress (obsessions).',35),
('rumination','🌀','Thinks about it again and again','thinking',10,'Goes over the same bad thing in their head for hours.','Rumination: repetitive negative thinking about distress and its causes.',36),
('no_gratitude','🙅','Never thankful','thinking',7,'Takes good things for granted and notices only what''s missing.','Low dispositional gratitude.',37),
('lacks_empathy','💔','Doesn''t feel others'' feelings','relationships',8,'Doesn''t notice or care how others feel.','Lack of empathy: unwilling to recognise or identify with the feelings and needs of others.',38),
('exploits_others','🪝','Uses people','relationships',12,'Is nice to people only to get something.','Interpersonally exploitative: takes advantage of others to achieve their own ends.',39),
('attention_seeking','📢','Must be the centre of attention','relationships',10,'Feels upset when others get the attention.','Uncomfortable in situations where they are not the centre of attention.',40),
('theatrical','🎬','Very dramatic','relationships',14,'Acts as if on a stage: big words, big gestures.','Self-dramatisation, theatricality and exaggerated expression of emotion; may use appearance to draw attention.',41),
('easily_influenced','🍃','Easily led by others','relationships',10,'Changes their opinion to match whoever is near.','Suggestibility: easily influenced by others or by circumstances.',42),
('unstable_relationships','🌪️','Stormy friendships','relationships',12,'Friendships start strong and end in big fights.','A pattern of unstable and intense interpersonal relationships.',43),
('avoids_people','🐚','Prefers to be alone','relationships',10,'Chooses to be alone almost always and doesn''t miss others.','Neither desires nor enjoys close relationships; almost always chooses solitary activities.',44),
('no_close_friends','🚶','No close friends','relationships',12,'Has nobody to share secrets with.','Lacks close friends or confidants other than first-degree relatives.',45),
('indifferent_praise','😐','Doesn''t care about praise or blame','relationships',12,'Praise and criticism don''t seem to touch them.','Appears indifferent to the praise or criticism of others.',46),
('fear_rejection','🙈','Avoids people for fear of rejection','relationships',10,'Stays away from others because they might not like them.','Avoids interpersonal contact because of fears of criticism, disapproval or rejection.',47),
('avoid_new','🧳','Avoids anything new','relationships',10,'Won''t try new things in case they look silly.','Unusually reluctant to take personal risks or engage in new activities for fear of embarrassment.',48),
('needs_reassurance','🫂','Needs others to decide','relationships',10,'Can''t choose even small things without asking someone.','Difficulty making everyday decisions without excessive advice and reassurance.',49),
('clingy','🧲','Can''t be alone','relationships',10,'Feels lost when alone; quickly finds someone new to lean on.','Uncomfortable or helpless when alone; urgently seeks another relationship when one ends.',50),
('cant_disagree','🤐','Can''t say no or disagree','relationships',8,'Agrees with everyone so they won''t be left.','Difficulty expressing disagreement because of fear of losing support or approval.',51),
('controlling','🎮','Controls others','relationships',10,'Everyone must do it exactly their way.','Reluctant to delegate or work with others unless they submit exactly to their way of doing things.',52),
('guards_relationship','🛡️','Watches a friend too closely','relationships',8,'Checks who their friend talks to and gets upset.','Relationship-guarding: vigilance and attempts to keep a rival away.',53),
('isolates_target','🏝️','Cuts you off from friends','relationships',12,'Tries to keep a person away from their friends and family.','Isolating a target from their social support.',54),
('breaks_rules','⛔','Breaks rules and laws','behaviour',12,'Breaks rules again and again, even serious ones.','Failure to conform to social norms and lawful behaviour.',55),
('deceitful','🃏','Lies and tricks for gain','behaviour',10,'Lies and tricks people to get things or for fun.','Deceitfulness: repeated lying, use of aliases, or conning others for profit or pleasure.',56),
('lies_often','🤥','Lies often','behaviour',6,'Says things that aren''t true, often.','Frequent lying.',57),
('impulsive','⚡','Acts without thinking','behaviour',8,'Does things first and thinks later.','Impulsivity or failure to plan ahead.',58),
('reckless','🏍️','Takes dangerous risks','behaviour',12,'Does dangerous things without caring who gets hurt.','Reckless disregard for the safety of self or others.',59),
('irresponsible','🗑️','Doesn''t keep promises or jobs','behaviour',12,'Doesn''t do their part or pay back what they owe.','Consistent irresponsibility in work or financial obligations.',60),
('aggressive','👊','Fights and threatens','behaviour',10,'Pushes, hits or threatens people.','Irritability and aggressiveness, such as repeated physical fights or assaults.',61),
('picks_on_weaker','🐁','Picks on someone weaker','behaviour',6,'Picks on the same smaller or quieter person again and again.','Repeated, intentional aggression involving an imbalance of power.',62),
('charm_manipulative','🎩','Charming to get what they want','behaviour',12,'Very sweet when they want something.','Superficial charm used as a tool to influence others.',63),
('cynical_strategic','♟️','Plans how to use people','behaviour',14,'Thinks of people as pieces in a game.','Machiavellianism: a cynical view of people and strategic, calculating manipulation for self-interest.',64),
('workaholic','💼','Work before friends and fun','behaviour',12,'Never has time to play or rest.','Excessive devotion to work and productivity, to the exclusion of leisure and friendships.',65),
('cant_throw_away','🗄️','Can''t throw things away','behaviour',12,'Keeps old, broken things "just in case".','Unable to discard worn-out or worthless objects even without sentimental value.',66),
('compulsions','🧼','Repeats actions to calm worry','behaviour',10,'Washes, checks or counts again and again to feel OK.','Repetitive behaviours or mental acts performed to reduce distress (compulsions).',67),
('hides_with_jokes','🤡','Jokes to hide feelings','behaviour',10,'Makes a joke whenever things get serious.','Humour used as a defensive, avoidant way of coping.',68),
('improves_self','🪜','Works harder after seeing others succeed','behaviour',7,'Seeing a friend win makes them practise more.','Motivation to improve one''s own position: typical of benign envy.',69),
('pulls_down','🪓','Tries to pull others down','behaviour',9,'Wants the other person to lose what they have.','Motivation to damage the envied person''s position: typical of malicious envy.',70),
('wants_what_others_have','🫴','Wants what others have','feelings',7,'Wishes they had what someone else has.','Desire for an advantage that another person has.',71),
('self_risk','🆘','Hurts themselves in crises','behaviour',18,null,'Recurrent self-harming or suicidal behaviour in crises: a reason for urgent professional help.',72),
('flashbacks','🎞️','Memories jump back','feelings',13,'Scary memories suddenly feel like they are happening again.','Intrusive memories and flashbacks of a traumatic event.',73),
('nightmares','🌙','Nightmares','feelings',8,'Has bad dreams about what happened.','Recurrent distressing dreams related to the event.',74),
('hypervigilance','👀','Always on alert','feelings',12,'Jumps at small noises and can''t relax.','Hypervigilance and an exaggerated startle response.',75),
('avoids_reminders','↩️','Avoids reminders','behaviour',12,'Stays away from places and things that remind them.','Avoidance of trauma-related thoughts, places or people.',76),
('needs_routine','🗓️','Needs routines','behaviour',8,'Gets upset when plans change.','Insistence on sameness and inflexible adherence to routines.',77),
('sensory','🔊','Sounds and lights feel too much','feelings',8,'Loud noise, bright light or scratchy clothes feel very strong.','Hyper- or hypo-reactivity to sensory input.',78),
('social_cues','🤔','Finds hints and jokes hard','relationships',8,'Doesn''t always understand hints, faces or jokes.','Persistent differences in social communication and interaction.',79),
('deep_interests','🚂','Deep favourite topics','behaviour',8,'Knows everything about one favourite subject.','Highly restricted, fixated interests that are unusual in intensity or focus.',80),
('odd_speech','💬','Unusual way of talking','behaviour',14,'Talks in a vague or strange way that is hard to follow.','Odd thinking and speech (vague, metaphorical, over-elaborate).',81),
('odd_behaviour','🦄','Unusual look or behaviour','behaviour',14,'Dresses or acts in a way others find very strange.','Behaviour or appearance that is odd, eccentric or peculiar.',82),
('gossip','🗣️','Talks about people behind their back','tactics',8,'Says bad things about someone who isn''t there.','Negative talk about absent third parties.',83),
('spreads_rumours','📨','Spreads rumours','tactics',9,'Passes on stories that might not be true, to make someone look bad.','Spreading unverified, damaging information about a target.',84),
('backhanded_compliment','🌹','Compliments with a sting','tactics',9,'"Nice drawing, for once!": praise with a hidden insult.','Backhanded compliments: praise that carries a criticism or put-down.',85),
('concerned_gossip','🫢','"I''m just worried about her…"','tactics',11,'Says bad things about someone while pretending to care.','Damaging information framed as concern, keeping the speaker deniable.',86),
('denies_reality','🌫️','"That never happened"','tactics',12,'Says things didn''t happen, so you doubt your own memory.','Denying events or statements so the target doubts their own memory or perception.',87),
('turns_tables','🔃','Turns the blame around','tactics',12,'When caught, acts as if they are the one being hurt.','Reversing the roles of victim and offender when confronted.',88),
('silent_punishment','🤫','Punishes with silence','tactics',8,'Stops talking to you to punish you.','Withdrawing communication as punishment or control (ostracism).',89),
('shuts_down','🧱','Shuts down in arguments','tactics',10,'Goes quiet and stops answering when there is a problem.','Stonewalling: emotional and conversational withdrawal during conflict.',90),
('uses_third_person','🔺','Brings others in to win','tactics',12,'"Even Mum agrees with me!": pulls a third person into a fight.','Drawing a third person into a two-person conflict to gain leverage or reduce tension.',91),
('too_much_too_soon','💝','Too much love, too soon','tactics',14,'Showers someone with gifts and attention very fast, to make them attached.','Overwhelming affection, attention and gifts early in a relationship to create dependence.',92),
('guilt_lever','🎗️','Makes you feel guilty','tactics',9,'"After all I did for you…" to get what they want.','Inducing guilt to gain compliance.',93),
('comes_back_sweet','🧹','Comes back sweet after hurting','tactics',15,'After hurting someone, returns with promises to pull them back.','Returning with affection or promises to resume a harmful relationship ("hoovering").',94),
('blames_own_flaws','📽️','Blames you for their own faults','tactics',11,'The lazy one calls everyone else lazy.','Projection: attributing one''s own unacceptable feelings or traits to others.',95),
('moves_goalposts','🥅','Keeps changing what''s "good enough"','tactics',11,'Whatever you do, it''s never enough: the target keeps moving.','Shifting the criteria so that the target can never satisfy them.',96)
insert into public.conditions as c (key, icon, name, kind, parent, cluster, min_age, aliases, about, helps, academic, sources, traits, academic_min_age, position) values
('bullying','🛑','Bullying','behaviour',null,null,6,'{}'::text[],null,null,'Repeated, intentional aggression (physical, verbal, relational or online) by someone with more power against someone who finds it hard to defend themselves. Bystanders strongly shape whether it continues.',array['Olweus, D. (1993). Bullying at School: What We Know and What We Can Do. Blackwell.','Salmivalli, C. (2010). Bullying and the peer group: A review. Aggression and Violent Behavior, 15(2), 112–120.']::text[],array['empathy','boundaries']::text[],16,0),
('lying','🤥','Lying','behaviour',null,null,6,'{}'::text[],null,null,'Deliberately making another person believe something false. In children it is normal in development; it becomes a concern when frequent, self-serving and combined with blaming others.','{}'::text[],array['truthful','self_honesty']::text[],16,1),
('low_self_esteem','🥀','Low self-esteem','issue',null,null,7,'{}'::text[],null,null,'A negative overall evaluation of one''s own worth. Linked to avoidance, depression and vulnerability to envy and jealousy; it is a risk factor, not a diagnosis.',array['Rosenberg, M. (1965). Society and the Adolescent Self-Image. Princeton University Press.']::text[],array['confidence']::text[],16,2),
('funny_mask','🎭','Living behind a funny mask','issue',null,null,10,'{}'::text[],null,null,'Using humour defensively to avoid painful feelings or conversations. Self-defeating humour styles are linked with lower well-being.',array['Martin, R. A., et al. (2003). Individual differences in uses of humor: the Humor Styles Questionnaire. Journal of Research in Personality, 37(1), 48–75.']::text[],array['humour','feelings']::text[],16,3),
('autism','🐠','Autism','condition',null,null,8,array['autism spectrum','Asperger''s']::text[],null,null,'Autism spectrum disorder: persistent differences in social communication and interaction, together with restricted, repetitive behaviours, interests or activities, present from early development. Support needs vary widely. "Asperger''s" is no longer a separate diagnosis in DSM-5.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).']::text[],'{}'::text[],16,4),
('ocd','🔁','OCD (obsessive-compulsive disorder)','condition',null,null,12,array['وسواس قهري']::text[],null,null,'Obsessions (intrusive, unwanted thoughts, urges or images) and/or compulsions (repetitive behaviours or mental acts aimed at reducing distress) that are time-consuming or cause significant distress. Different from OCPD, a personality pattern.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).']::text[],array['conscience']::text[],16,5),
('ptsd','⚡','PTSD (post-traumatic stress disorder)','condition',null,null,13,'{}'::text[],null,null,'After exposure to a traumatic event: intrusion symptoms (memories, nightmares, flashbacks), avoidance, negative changes in thinking and mood, and heightened arousal, lasting more than a month.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).']::text[],array['feelings']::text[],16,6),
('toxic','☠️','Toxic (poisonous) behaviour','behaviour',null,null,13,array['poisoned personality']::text[],null,null,'A popular, non-clinical term for a repeated pattern of behaviour that harms others'' well-being: belittling, manipulation, guilt-induction and chronic victimhood. Useful in everyday language, but not a diagnosis.','{}'::text[],array['boundaries','empathy','encouraging']::text[],16,7),
('lucifer_effect','🎭','The Lucifer effect','idea',null,null,15,'{}'::text[],null,null,'Zimbardo''s term for the transformation of ordinary people into perpetrators under situational and systemic pressures (roles, anonymity, authority, dehumanisation). Its main evidence, the 1971 Stanford Prison Experiment, has been strongly criticised for its methods.',array['Zimbardo, P. (2007). The Lucifer Effect: Understanding How Good People Turn Evil. Random House.','Le Texier, T. (2019). Debunking the Stanford Prison Experiment. American Psychologist, 74(7), 823–839.']::text[],array['conscience','boundaries']::text[],16,8),
('paranoid_pd','🕵️','Paranoid personality disorder','disorder',null,'A',16,'{}'::text[],'Someone who trusts nobody and believes people are secretly against them, without proof.','Clinicians and therapy; a calm, honest and predictable way of talking helps build trust.','Cluster A. Pervasive distrust and suspiciousness: others'' motives are read as malevolent. Suspects exploitation without basis, doubts loyalty, won''t confide, reads threats into benign remarks, bears grudges, perceives attacks on character and counter-attacks quickly. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['thinking']::text[],16,9),
('schizoid_pd','🐚','Schizoid personality disorder','disorder',null,'A',16,'{}'::text[],'Someone who prefers to be alone almost always and shows very little feeling.','Respecting their need for space; clinicians if they are suffering.','Cluster A. Pervasive detachment from social relationships and a restricted range of emotional expression: no desire for close relationships, solitary activities, little pleasure, indifference to praise or criticism, emotional coldness. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],'{}'::text[],16,10),
('schizotypal_pd','🔮','Schizotypal personality disorder','disorder',null,'A',16,'{}'::text[],'Someone with unusual beliefs, an unusual way of talking or dressing, and great discomfort with close relationships.','Clinicians; patience and acceptance.','Cluster A. Acute discomfort with close relationships plus cognitive or perceptual distortions and eccentric behaviour: ideas of reference, odd beliefs or magical thinking, unusual perceptions, odd speech, suspiciousness, social anxiety that does not lessen with familiarity. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],'{}'::text[],16,11),
('antisocial_pd','⛔','Antisocial personality disorder','disorder',null,'B',16,'{}'::text[],'Someone who keeps breaking rules, lying and hurting others without feeling sorry.','Clinicians and the law; people around them need protection and clear limits.','Cluster B. Pervasive disregard for and violation of the rights of others: unlawful behaviour, deceitfulness, impulsivity, aggressiveness, reckless disregard for safety, consistent irresponsibility and lack of remorse. Diagnosed only from age 18, with evidence of conduct disorder before 15. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['conscience','empathy']::text[],16,12),
('bpd','🌊','Borderline personality disorder (BPD)','disorder',null,'B',16,array['BPD']::text[],null,'Doctors and therapists: Dialectical Behaviour Therapy (DBT) has good evidence; patience and clear boundaries from others.','Cluster B. Pervasive instability of relationships, self-image and emotions, with marked impulsivity: frantic efforts to avoid abandonment, idealisation-devaluation, identity disturbance, impulsivity, recurrent self-harm or suicidal behaviour, affective instability, chronic emptiness, intense anger, and stress-related paranoid ideas or dissociation. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).','Linehan, M. M. (1993). Cognitive-Behavioral Treatment of Borderline Personality Disorder. Guilford Press.']::text[],array['feelings','boundaries','thinking']::text[],16,13),
('histrionic_pd','🎬','Histrionic personality disorder','disorder',null,'B',16,'{}'::text[],'Someone who always needs to be the centre of attention, with big, dramatic feelings that change fast.','Clinicians and therapy.','Cluster B. Pervasive excessive emotionality and attention-seeking: discomfort when not the centre of attention, rapidly shifting and shallow emotions, use of appearance to draw attention, theatricality, suggestibility, and considering relationships more intimate than they are. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['feelings']::text[],16,14),
('narcissistic','🪞','Narcissistic personality disorder','disorder',null,'B',16,array['narcissist']::text[],null,'Doctors and therapists. People around them may need strong boundaries.','Cluster B. Pervasive pattern of grandiosity (in fantasy or behaviour), need for admiration and lack of empathy: inflated self-importance, fantasies of success or power, belief in being special, entitlement, exploitation, envy, arrogance. Research describes two forms: grandiose and vulnerable ("covert"). A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).','Pincus, A. L., & Lukowitsky, M. R. (2010). Pathological narcissism and narcissistic personality disorder. Annual Review of Clinical Psychology, 6, 421–446.']::text[],array['empathy','confidence']::text[],16,15),
('grandiose_narcissism','👑','Grandiose (overt) narcissism','disorder','narcissistic','B',16,array['overt narcissist']::text[],'The loud kind: openly shows off, dominates and expects admiration.','Clear limits; not feeding the need for admiration.','Subtype described in research (not a separate DSM diagnosis): overt self-enhancement, dominance, exhibitionism, entitlement and interpersonal exploitation, with relatively high self-reported self-esteem.',array['Wink, P. (1991). Two faces of narcissism. Journal of Personality and Social Psychology, 61(4), 590–597.','Pincus & Lukowitsky (2010), see above.']::text[],array['confidence','empathy']::text[],16,16),
('vulnerable_narcissism','🫥','Vulnerable (covert) narcissism','disorder','narcissistic','B',16,array['covert narcissist','covert narcissism']::text[],'The quiet kind: seems shy or modest, but secretly feels special, is deeply hurt by criticism, envies others and holds grudges.','Therapy; honest, steady relationships with clear boundaries.','Subtype described in research ("covert narcissism" in popular language; not a separate DSM diagnosis): hidden grandiose expectations with shame, hypersensitivity to evaluation, social withdrawal, resentment, envy and fragile self-esteem.',array['Wink, P. (1991). Two faces of narcissism. Journal of Personality and Social Psychology, 61(4), 590–597.','Pincus & Lukowitsky (2010), see above.']::text[],array['confidence','gratitude']::text[],16,17),
('malignant_narcissism','🦂','Malignant narcissism','disorder','narcissistic','B',18,'{}'::text[],'The most dangerous mix: narcissism with cruelty, suspicion and no guilt.','Professionals; the people hurt need protection.','A clinical concept from Otto Kernberg (not a DSM diagnosis): narcissistic personality combined with antisocial behaviour, ego-syntonic aggression or sadism, and paranoid features.',array['Kernberg, O. F. (1984). Severe Personality Disorders: Psychotherapeutic Strategies. Yale University Press.']::text[],array['empathy','conscience']::text[],18,18),
('avoidant_pd','🙈','Avoidant personality disorder','disorder',null,'C',16,'{}'::text[],'Someone who wants friends but stays away from people because they are terrified of being judged.','Therapy; gentle, patient friends.','Cluster C. Pervasive social inhibition, feelings of inadequacy and hypersensitivity to negative evaluation: avoids contact for fear of criticism, restrained in close relationships, preoccupied with rejection, views self as inferior, reluctant to take risks. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['confidence','assertive']::text[],16,19),
('dependent_pd','🧲','Dependent personality disorder','disorder',null,'C',16,'{}'::text[],'Someone who can''t make choices alone, can''t say no, and is terrified of being left on their own.','Therapy that builds confidence and independence.','Cluster C. Pervasive, excessive need to be taken care of, leading to submissive, clinging behaviour and fears of separation: difficulty with everyday decisions, needs others to take responsibility, can''t disagree, discomfort when alone. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['assertive','decisions']::text[],16,20),
('ocpd','📐','Obsessive-compulsive personality disorder (OCPD)','disorder',null,'C',16,'{}'::text[],'Someone so focused on rules, order and perfection that work never gets finished and friends come last. Different from OCD.','Therapy; learning that "good enough" is OK.','Cluster C. Pervasive preoccupation with orderliness, perfectionism and control at the expense of flexibility and efficiency: rules and lists, perfectionism that blocks completion, devotion to work, rigidity, reluctance to delegate, hoarding of worthless objects. Unlike OCD, the pattern usually feels right to the person. A personality disorder is a long-lasting pattern of inner experience and behaviour that differs markedly from cultural expectations, is inflexible, begins by adolescence or early adulthood, and causes distress or impairment. Only a qualified clinician can diagnose it.',array['American Psychiatric Association (2022). Diagnostic and Statistical Manual of Mental Disorders, 5th ed., text revision (DSM-5-TR).','World Health Organization. ICD-11: personality disorders and related traits (6D10–6D11).']::text[],array['thinking']::text[],16,21),
('dark_triad','🌑','The dark triad','idea',null,null,16,'{}'::text[],'Three dark personality traits that often go together: narcissism, Machiavellianism (scheming) and psychopathy (cold, no guilt).','Knowing the signs helps protect yourself.','Three overlapping, socially aversive traits measured in the general population (not diagnoses): narcissism, Machiavellianism and subclinical psychopathy. Shared core: callousness and manipulation.',array['Paulhus, D. L., & Williams, K. M. (2002). The dark triad of personality. Journal of Research in Personality, 36(6), 556–563.']::text[],array['empathy','conscience']::text[],16,22),
('dark_tetrad','🌚','The dark tetrad','idea',null,null,18,'{}'::text[],'The dark triad plus everyday sadism: enjoying other people''s pain.','Knowing the signs helps protect yourself.','The dark triad plus everyday sadism, which predicts cruelty beyond the other three traits.',array['Buckels, E. E., Jones, D. N., & Paulhus, D. L. (2013). Behavioral confirmation of everyday sadism. Psychological Science, 24(11), 2201–2209.']::text[],array['empathy','conscience']::text[],18,23),
('machiavellianism','♟️','Machiavellianism','idea','dark_triad',null,15,'{}'::text[],'Treating people as pieces in a game: charming, calculating, and always working for themselves.','Noticing patterns, not words; keeping your own boundaries.','Dark-triad trait named after Niccolò Machiavelli: cynical views of human nature, strategic manipulation and a focus on self-interest over morality. Measured with the Mach-IV scale.',array['Christie, R., & Geis, F. L. (1970). Studies in Machiavellianism. Academic Press.']::text[],array['conscience']::text[],16,24),
('psychopathy','🧊','Psychopathy','idea','dark_triad',null,16,'{}'::text[],'Very cold personality: no guilt, no fear, charming on the outside, and often reckless.','Professionals; protection for others.','A personality construct (not a DSM diagnosis; overlaps with antisocial PD): shallow affect, callousness, lack of remorse, superficial charm, impulsivity and irresponsibility. Assessed in research and forensic settings with Hare''s PCL-R.',array['Hare, R. D. (2003). The Hare Psychopathy Checklist–Revised (2nd ed.). Multi-Health Systems.']::text[],array['empathy','conscience']::text[],16,25),
('sadism','🖤','Sadism','disorder','dark_tetrad',null,18,'{}'::text[],null,null,'Enjoyment of others'' pain or humiliation. "Everyday sadism" is studied as the fourth dark-tetrad trait. (Sadistic personality disorder appeared only in the appendix of DSM-III-R and is not a current diagnosis.)',array['Buckels, E. E., Jones, D. N., & Paulhus, D. L. (2013). Behavioral confirmation of everyday sadism. Psychological Science, 24(11), 2201–2209.']::text[],array['empathy','conscience']::text[],16,26),
('character_assassination','🗡️','Character assassination','tactic',null,null,10,array['smear campaign']::text[],'Trying to ruin someone''s good name by spreading bad stories about them, true or not.','Stay calm, keep facts, tell trusted people; don''t spread it further.','A deliberate, sustained effort to damage a person''s reputation and credibility, through rumours, distortion, ridicule or selective disclosure.',array['Samoilenko, S. A., Icks, M., Keohane, J., & Shiraev, E. (Eds.) (2020). Routledge Handbook of Character Assassination and Reputation Management. Routledge.']::text[],array['truthful','empathy']::text[],16,27),
('silent_assassination','🫢','Silent character assassination','tactic','character_assassination',null,11,array['whisper campaign']::text[],'Quiet damage to someone''s name: small hints, "worried" whispers and compliments with a sting, so nobody can say they attacked.','Ask directly, "What do you mean?"; speak to the person, not about them.','A covert form of reputational aggression (also called a whisper campaign): innuendo, feigned concern, backhanded compliments and strategic omissions that preserve the aggressor''s deniability. Related to relational/indirect aggression.',array['Crick, N. R., & Grotpeter, J. K. (1995). Relational aggression, gender, and social-psychological adjustment. Child Development, 66(3), 710–722.']::text[],array['truthful','empathy']::text[],16,28),
('gaslighting','🌫️','Gaslighting','tactic',null,null,13,'{}'::text[],'Making someone doubt their own memory or feelings: "That never happened", "You''re too sensitive".','Write things down; check with people you trust; your feelings are real.','Manipulation that leads a target to doubt their own perceptions, memory or sanity. Named after the play and film Gaslight (1938/1944); described sociologically as rooted in power inequalities.',array['Sweet, P. L. (2019). The sociology of gaslighting. American Sociological Review, 84(5), 851–875.']::text[],array['truthful']::text[],16,29),
('triangulation','🔺','Triangulation','tactic',null,null,13,'{}'::text[],'Pulling a third person into a problem between two people, to win or to make someone jealous.','Talk directly to the person you have the problem with.','Bowen family-systems concept: a two-person relationship under tension draws in a third person to stabilise it; used manipulatively to gain allies or provoke jealousy.',array['Bowen, M. (1978). Family Therapy in Clinical Practice. Jason Aronson.']::text[],array['boundaries']::text[],16,30),
('love_bombing','💝','Love bombing','tactic',null,null,15,'{}'::text[],'Too much love, gifts and attention too fast, so the other person becomes attached and easier to control.','Healthy relationships grow slowly; watch what happens after the start.','Overwhelming displays of affection and attention early in a relationship to create dependence. The term comes from studies of cult recruitment in the 1970s.','{}'::text[],array['boundaries']::text[],16,31),
('silent_treatment','🤫','The silent treatment','tactic',null,null,8,'{}'::text[],'Stopping talking to someone on purpose, to punish them.','Say "I''m upset and need time" instead; then talk.','Deliberate withdrawal of communication as punishment or control: a form of ostracism that threatens belonging, self-esteem, control and meaningful existence.',array['Williams, K. D. (2001). Ostracism: The Power of Silence. Guilford Press.']::text[],array['feelings','assertive']::text[],16,32),
('stonewalling','🧱','Stonewalling','tactic',null,null,12,'{}'::text[],'Shutting down in an argument: no answers, no looking, like talking to a wall.','Take a short break, then come back to talk.','Emotional and conversational withdrawal during conflict; one of Gottman''s "Four Horsemen" that predict relationship breakdown.',array['Gottman, J. M. (1994). What Predicts Divorce? Lawrence Erlbaum.']::text[],array['feelings']::text[],16,33),
('darvo','🔃','DARVO','tactic',null,null,15,'{}'::text[],'When caught: Deny it, Attack the person who complained, and act like the real victim.','Stick to the facts; get support.','Deny, Attack, Reverse Victim and Offender: a response pattern of perpetrators when held accountable, which increases the doubt and self-blame of the accuser.',array['Freyd, J. J. (1997). Violations of power, adaptive blindness, and betrayal trauma theory. Feminism & Psychology, 7(1), 22–32.']::text[],array['responsibility']::text[],16,34),
('projection','📽️','Projection','tactic',null,null,12,'{}'::text[],'Blaming someone else for your own bad feelings or faults.','Ask, "Is this really about me?"','A defence mechanism in which one''s own unacceptable impulses, feelings or traits are attributed to others.',array['Freud, A. (1936). The Ego and the Mechanisms of Defence.']::text[],array['self_honesty']::text[],16,35),
('guilt_tripping','🎗️','Guilt-tripping','tactic',null,null,9,'{}'::text[],'Making someone feel guilty so they do what you want: "After all I did for you…"','You can be kind and still say no.','Inducing guilt as an interpersonal influence strategy to gain compliance; effective in close relationships but breeds resentment.',array['Baumeister, R. F., Stillwell, A. M., & Heatherton, T. F. (1994). Guilt: An interpersonal approach. Psychological Bulletin, 115(2), 243–267.']::text[],array['assertive']::text[],16,36),
('hoovering','🧹','Hoovering','tactic',null,null,16,'{}'::text[],'After hurting someone and leaving, coming back with sweet promises to pull them back in.','Look at what they do, not what they promise.','Popular (non-clinical) term for attempts to draw a person back into a harmful relationship through affection, promises or crises.','{}'::text[],array['boundaries']::text[],16,37),
('envy','💚','Envy','emotion',null,null,7,array['حسد']::text[],'The painful feeling of wanting what someone else has. It is normal; what we do with it matters.','Gratitude, focusing on your own path, and turning envy into effort.','An unpleasant emotion arising when another person has an advantage in a domain relevant to oneself. Research links it to perceived inferiority, low self-esteem, zero-sum beliefs and low gratitude.',array['Smith, R. H., & Kim, S. H. (2007). Comprehending envy. Psychological Bulletin, 133(1), 46–64.','McCullough, M. E., Emmons, R. A., & Tsang, J.-A. (2002). The grateful disposition. Journal of Personality and Social Psychology, 82(1), 112–127.']::text[],array['gratitude','confidence','mindset']::text[],16,38),
('benign_envy','🪜','Benign envy (the useful kind)','emotion','envy',null,9,array['غبطة']::text[],'Envy that makes you try harder: "I want to be good at that too."','Learn from the person; ask how they did it.','Envy that motivates moving oneself up ("levelling up"), without wishing harm to the other.',array['van de Ven, N., Zeelenberg, M., & Pieters, R. (2009). Leveling up and down: The experiences of benign and malicious envy. Emotion, 9(3), 419–429.']::text[],array['drive']::text[],16,39),
('malicious_envy','🪓','Malicious envy (the harmful kind)','emotion','envy',null,10,'{}'::text[],'Envy that wants the other person to lose what they have.','Gratitude, talking about it, and seeing that their success doesn''t take yours away.','Envy that motivates pulling the other down ("levelling down"), associated with schadenfreude and hostile behaviour.',array['van de Ven, N., Zeelenberg, M., & Pieters, R. (2009). Leveling up and down: The experiences of benign and malicious envy. Emotion, 9(3), 419–429.']::text[],array['gratitude','mindset']::text[],16,40),
('jealousy','🫣','Jealousy','emotion',null,null,7,array['غيرة']::text[],'The fear of losing someone you love to another person. Everyone feels it sometimes; it becomes a problem when it controls you.','Talking about the fear, building trust, and healthy self-esteem.','An emotion triggered by a perceived threat to a valued relationship from a rival. Different from envy (wanting what another has). Normal and partly evolved; stronger with low self-esteem and insecure attachment.',array['Buss, D. M. (2000). The Dangerous Passion: Why Jealousy Is as Necessary as Love and Sex. Free Press.']::text[],array['confidence']::text[],16,41)
