on conflict (id) do update set name=excluded.name, emoji=excluded.emoji, age=excluded.age, sex=excluded.sex, education=excluded.education, role=excluded.role, min_age=excluded.min_age, bio=excluded.bio, traits=excluded.traits, conditions=excluded.conditions, signs=excluded.signs, cond_levels=excluded.cond_levels;
select (select count(*) from public.signs) as signs, (select count(*) from public.conditions) as conditions, (select count(*) from public.condition_signs) as links, (select count(*) from public.traits) as traits, (select count(*) from public.characters) as characters;
